test("grades editable scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-settle", "clerk");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "clerk-limit-C", "0.50");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  await ui.setSetting(pg_uma, "score-log", "on");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": "ben@x", "tags": "b, a"}));
  expect(await ui.addNote(pg_uma, "x")).toBe(true);
  expect(await ui.periodAction(pg_uma, "2026-04", "close")).toBe(true);
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-02-10"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ada, "Ben")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.watch(pg_wes, p_ada, true)).toBe(true);
  expect(await ui.pasteClaims(pg_wes, "Ben,1.00,2026-03-15,\nAda,0.40,2026-02-25,")).toBeNull();
  await ui.refresh(pg_wes);
  expect(await ui.statement(pg_wes, p_ada)).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.delegate(pg_wes, {"user": "vic", "from": "2026-03-01", "to": "2026-04-02"})).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.pasteClaims(pg_vic, "Ben,12.50,,a, b")).toBe(1);
  const c_ben_0 = await ui.claimAt(pg_vic, p_ben, 0);
  expect(await ui.periodAction(pg_vic, "2026-02", "close")).toBe(true);
  expect(await ui.search(pg_vic, "e")).toEqual([`${sheet} Ben (A) 1.25`]);
  expect(await ui.shareClaim(pg_vic, c_ben_0, "Ada", "25.00")).toBe(true);
  expect(await ui.editPerson(pg_vic, p_ben, {"terms": "3"})).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.hold(pg_vic, p_ada, {"from": "2026-02-10", "to": "2026-03-20"})).toBe(true);
